import { Link } from 'react-router-dom';
import Card from '../../components/Card';

const STEPS = [
  {
    step: '01', icon: '📦', title: 'Submit Your Waste',
    desc: 'Log your waste through our platform by selecting the type (Dry, Wet, or E-Waste) and entering the weight. Or schedule a doorstep pickup.',
    details: ['Dry Waste: paper, plastic, metal', 'Wet Waste: food scraps, organic', 'E-Waste: electronics, batteries'],
  },
  {
    step: '02', icon: '⚖️', title: 'Waste is Sorted & Rewards Calculated',
    desc: 'Our system automatically calculates your reward based on waste type and weight. Points and money are instantly credited to your wallet.',
    details: ['Dry: ₹2/kg + 1pt/kg', 'Wet: ₹1/kg + 1pt/kg', 'E-Waste: ₹5/kg + 1pt/kg'],
  },
  {
    step: '03', icon: '♻️', title: 'Waste Sent to Recyclers',
    desc: 'Collected waste is batched in our inventory and assigned to certified recycling partners, ensuring responsible end-to-end processing.',
    details: ['Inventory tracking', 'Certified recycler assignment', 'Full chain transparency'],
  },
];

const HowItWorksPage = () => (
  <div style={{ background: 'var(--eco-bg)', minHeight: '100vh' }}>

    <div className="section-header">
      <h1 className="section-header__title">How EcoTrack Works</h1>
      <p className="section-header__subtitle">Three simple steps turn your waste into rewards while helping the environment.</p>
    </div>

    <div className="container--lg" style={{ padding: 'var(--space-16) var(--space-6)' }}>
      <div className="flex-col gap-8">
        {STEPS.map((s, i) => (
          <div key={s.step} style={{ display: 'grid', gridTemplateColumns: '80px 1fr', gap: 'var(--space-6)', alignItems: 'start' }}>
            <div style={{ textAlign: 'center' }}>
              <div className="step-dot" style={{ margin: '0 auto' }}>{s.step}</div>
              {i < STEPS.length - 1 && <div className="step-connector" />}
            </div>
            <Card>
              <Card.Body>
                <div className="flex gap-4 mb-4" style={{ alignItems: 'center' }}>
                  <span style={{ fontSize: 36 }}>{s.icon}</span>
                  <h2 style={{ fontFamily: 'var(--font-display)', fontSize: 'var(--text-xl)', fontWeight: 700 }}>{s.title}</h2>
                </div>
                <p style={{ color: 'var(--eco-text-secondary)', lineHeight: 1.7, marginBottom: 'var(--space-4)' }}>{s.desc}</p>
                <div className="flex gap-2" style={{ flexWrap: 'wrap' }}>
                  {s.details.map(d => (
                    <span key={d} className="chip" style={{ color: 'var(--eco-primary)', borderColor: 'var(--eco-border-strong)' }}>✓ {d}</span>
                  ))}
                </div>
              </Card.Body>
            </Card>
          </div>
        ))}
      </div>

      <div className="cta-banner mt-8" style={{ marginTop: 'var(--space-12)' }}>
        <h3 className="cta-banner__title">Start Your Eco Journey Today</h3>
        <Link to="/register" className="btn btn--white btn--lg">Create Free Account →</Link>
      </div>
    </div>
  </div>
);

export default HowItWorksPage;
